fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Ensure the input vectors have the same length
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");
    
    // Perform element-wise subtraction and collect the results into a new Vec<i32>
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a - b)
        .collect()
}

